export const getListCompanyRecordsUrl = (id: number,
    params?: ListCompanyRecordsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/companies/${id}/records?${stringifiedParams}` : `/api/companies/${id}/records`
}

